SELECT 'sgso_relato_notificacoes' tbl,SUM(empresa_id=1) e1,SUM(empresa_id=6) e6,SUM(empresa_id NOT IN(1,6) AND empresa_id IS NOT NULL) o,SUM(empresa_id IS NULL) n,0 sd,COUNT(*) t FROM sgso_relato_notificacoes UNION ALL SELECT 'sgso_relato_perigos' tbl,SUM(empresa_id=1) e1,SUM(empresa_id=6) e6,SUM(empresa_id NOT IN(1,6) AND empresa_id IS NOT NULL) o,SUM(empresa_id IS NULL) n,0 sd,COUNT(*) t FROM sgso_relato_perigos UNION ALL SELECT 'sgso_relato_privacidade' tbl,SUM(empresa_id=1) e1,SUM(empresa_id=6) e6,SUM(empresa_id NOT IN(1,6) AND empresa_id IS NOT NULL) o,SUM(empresa_id IS NULL) n,0 sd,COUNT(*) t FROM sgso_relato_privacidade UNION ALL SELECT 'sgso_relato_workflow_eventos' tbl,SUM(empresa_id=1) e1,SUM(empresa_id=6) e6,SUM(empresa_id NOT IN(1,6) AND empresa_id IS NOT NULL) o,SUM(empresa_id IS NULL) n,0 sd,COUNT(*) t FROM sgso_relato_workflow_eventos UNION ALL SELECT 'sgso_relatos' tbl,SUM(empresa_id=1) e1,SUM(empresa_id=6) e6,SUM(empresa_id NOT IN(1,6) AND empresa_id IS NOT NULL) o,SUM(empresa_id IS NULL) n,SUM(deleted_at IS NOT NULL) sd,COUNT(*) t FROM sgso_relatos;